#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply = [&](int x, int y){
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    // Place element (target+1) at position target, for target = 0..n-3
    for(int target=0; target<n-1; target++){
        int pos=-1;
        for(int i=0;i<n;i++) if(p[i]==target+1){pos=i;break;}
        if(pos==target) continue;

        // We need at least 3 elements remaining (target..n-1) to do an operation
        // on the subproblem. But operations are global.
        // Strategy: first move element to position n-1, then from n-1 to target.

        if(pos!=n-1){
            // Move element at pos to position n-1.
            // After op(x,y): element at pos goes to:
            //   if pos < x: position (n-y) + (n-y - (n-y)) ... let me recount
            //   new array: [n-y..n-1] [x..n-y-1] [0..x-1]
            //   if pos >= n-y: new position = pos - (n-y)  (it's in the suffix part)
            //   if x <= pos < n-y: new position = y + (pos - x)  (middle part)
            //   if pos < x: new position = y + (n-y-x) + pos = n - x + pos  (prefix part)

            // Want new position = n-1.
            // From prefix: n-x+pos = n-1 => x = pos+1. Need y>=1, x+y<n => y < n-pos-1. Need pos < x = pos+1 ✓. Need pos+1<n => pos<n-1 ✓. Need n-pos-1>1 => pos<n-2.
            if(pos < n-2){
                apply(pos+1, 1);
            } else {
                // pos == n-2. From suffix part: pos-(n-y)=n-1 => y=n-1-1=... doesn't work easily.
                // From middle: y+(pos-x)=n-1 => y+n-2-x=n-1 => y-x=1 => y=x+1. x+y<n => 2x+1<n => x<(n-1)/2. x>=1,y>=2,x<n-2-x => need n-2>=x+1 i.e. x<=n-3.
                // Take x=1,y=2: element at n-2 goes to middle? x=1, n-y=n-2. pos=n-2 >= n-y=n-2 => suffix part. New pos = pos-(n-y)=0. Then move from 0 to n-1.
                apply(1, 2); // element goes to position 0
                // Now move from 0 to n-1: x=1, y=1 => new pos = n-1+0=n-1. ✓ (prefix: n-x+pos=n-1)
                apply(1, 1);
            }
        }

        // Now element is at position n-1
        // Move from n-1 to target: suffix part. op(x,y) with y=target+1: pos n-1 goes to position (n-1)-(n-y)=y-1=target. Need x>=1, x+y<n => x< n-target-1. x=1.
        if(1 + target + 1 < n){
            apply(1, target+1);
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
